def allowed(line):
    if line.startswith("REFUSED: "):
        parts=line.split(": ",2)
        return len(parts)==3 and parts[1] in ("input_verification","after_computation_started") and parts[2] in ALLOWED_LABELS
    return any(re.fullmatch(p,line) for p in PATTERNS)

def count(path):
    return sum(not allowed(line) for line in Path(path).read_text(errors="replace").splitlines())
